'use strict';

const rows = $input.all().flatMap(item => {
  const value = item.json?.body ?? item.json ?? {};
  if (Array.isArray(value)) return value;
  if (Array.isArray(value.data)) return value.data;
  return [value];
});
const uuid = value => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ''));
return rows
  .filter(row =>
    row &&
    uuid(row.route_id) &&
    uuid(row.lease_token) &&
    Number.isSafeInteger(Number(row.route_version)) &&
    String(row.content || '').trim() &&
    String(row.classifier_instruction || '').trim()
  )
  .map(row => ({
    json: {
      ...row,
      stateDateProbeClaim: row,
      stateDateProbeClaimReady: true
    }
  }));

'use strict';

const input = $input.first()?.json || {};
const claim = input.stateDateProbeClaim || input;
const instruction = String(claim.classifier_instruction || '').trim();
const content = String(claim.content || '').trim().slice(0, 12000);
const model = String(claim.classifier_model || '').trim();
const ready = Boolean(instruction && content && model);
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['contractVersion', 'aboutSelf', 'describesDay', 'decision', 'confidence', 'evidenceText'],
  properties: {
    contractVersion: { type: 'string', const: 'chelsea_state_date_probe_v1' },
    aboutSelf: { type: 'boolean' },
    describesDay: { type: 'boolean' },
    decision: { type: 'string', enum: ['ask', 'today'] },
    confidence: { type: 'number', minimum: 0, maximum: 1 },
    evidenceText: { anyOf: [{ type: 'string', maxLength: 300 }, { type: 'null' }] }
  }
};
const stateDateProbeRequest = ready ? {
  model,
  input: [
    { role: 'system', content: [{ type: 'input_text', text: instruction }] },
    {
      role: 'user',
      content: [{
        type: 'input_text',
        text: JSON.stringify({
          contractVersion: 'chelsea_state_date_probe_input_v1',
          message: content
        })
      }]
    }
  ],
  temperature: 0,
  text: {
    format: {
      type: 'json_schema',
      name: 'chelsea_state_date_probe_v1',
      strict: true,
      schema
    }
  }
} : {};

return [{
  json: {
    ...input,
    stateDateProbeReady: ready,
    stateDateProbeRequest,
    stateDateProbeSourceText: content,
    stateDateProbeSchema: schema
  }
}];

'use strict';

const root = $('Code | Build State Date Probe Request | StateDateRoute').item.json || {};
const incoming = $input.first()?.json || {};
const response = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const sourceText = String(root.stateDateProbeSourceText || '').normalize('NFKC');
const extractText = value => {
  if (typeof value?.output_text === 'string') return value.output_text;
  if (Array.isArray(value?.output)) {
    for (const output of value.output) {
      if (!Array.isArray(output?.content)) continue;
      for (const part of output.content) {
        if (typeof part?.text === 'string') return part.text;
        if (typeof part?.json === 'object' && part.json) return JSON.stringify(part.json);
      }
    }
  }
  if (typeof value?.choices?.[0]?.message?.content === 'string') {
    return value.choices[0].message.content;
  }
  return '';
};
const raw = extractText(response).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed = null;
let parseError = '';
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parseError = String(error?.message || error);
}
const keys = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
  ? Object.keys(parsed).sort()
  : [];
const expectedKeys = ['aboutSelf', 'confidence', 'contractVersion', 'decision', 'describesDay', 'evidenceText'];
const evidence = parsed?.evidenceText;
const validEvidence = evidence === null ||
  (typeof evidence === 'string' && evidence.length <= 300 &&
   evidence.length > 0 && sourceText.includes(evidence.normalize('NFKC')));
const factDecisionConsistent = parsed?.aboutSelf === true && parsed?.describesDay === true
  ? parsed?.decision === 'ask'
  : parsed?.decision === 'today';
const valid = Boolean(
  parsed &&
  keys.length === expectedKeys.length &&
  keys.every((key, index) => key === expectedKeys[index]) &&
  parsed.contractVersion === 'chelsea_state_date_probe_v1' &&
  typeof parsed.aboutSelf === 'boolean' &&
  typeof parsed.describesDay === 'boolean' &&
  ['ask', 'today'].includes(parsed.decision) &&
  Number.isFinite(parsed.confidence) &&
  parsed.confidence >= 0 &&
  parsed.confidence <= 1 &&
  validEvidence &&
  factDecisionConsistent
);

return [{
  json: {
    ...root,
    stateDateProbeValid: valid,
    stateDateProbeResult: valid ? parsed : null,
    stateDateProbeRaw: raw.slice(0, 4000),
    stateDateProbeError: valid
      ? ''
      : (parseError || 'state_date_probe_contract_invalid').slice(0, 1000)
  }
}];

