'use strict';

const input = $input.first()?.json || {};
const claim = input.stateDatePromptClaim || input;
const clean = (value, limit = 0) => {
  const text = String(value ?? '').normalize('NFKC').trim();
  return limit > 0 ? text.slice(0, limit) : text;
};
const routeId = clean(claim.route_id, 80);
const principalId = clean(claim.principal_id, 200);
const chatId = clean(claim.telegram_chat_id, 120);
const token = clean(claim.callback_token, 32);
const promptText = clean(claim.prompt_text, 500);
const yesterdayText = clean(claim.yesterday_button_text, 64);
const todayText = clean(claim.today_button_text, 64);
const yesterdayData = `chelsea_state_date:v1:y:${token}`;
const todayData = `chelsea_state_date:v1:t:${token}`;
const callbackPattern = /^chelsea_state_date:v1:[yt]:[a-f0-9]{32}$/;
const ready = Boolean(
  routeId &&
  principalId &&
  chatId &&
  promptText &&
  yesterdayText &&
  todayText &&
  callbackPattern.test(yesterdayData) &&
  callbackPattern.test(todayData) &&
  yesterdayData.length <= 64 &&
  todayData.length <= 64
);
const sendKey = `state_date_prompt:${routeId}:${token}`;
const inlineKeyboard = {
  rows: [{
    row: {
      buttons: [
        { text: yesterdayText, additionalFields: { callback_data: yesterdayData } },
        { text: todayText, additionalFields: { callback_data: todayData } }
      ]
    }
  }]
};

return [{
  json: {
    ...input,
    stateDatePromptReady: ready,
    stateDatePromptRouteId: routeId,
    stateDatePromptPrincipalId: principalId,
    stateDatePromptChatId: chatId,
    stateDatePromptText: promptText,
    stateDatePromptInlineKeyboard: inlineKeyboard,
    stateDatePromptSendKey: sendKey,
    stateRpcBody: ready ? {
      p_route_id: routeId,
      p_lease_token: String(claim.lease_token || ''),
      p_expected_route_version: Number(claim.route_version),
      p_send_key: sendKey
    } : {}
  }
}];

'use strict';

const root = $('Code | Build State Date Prompt | StateDateRoute').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const valid = body && typeof body === 'object' &&
  body.contractVersion === 'chelsea_state_date_prompt_begin_v1' &&
  String(body.routeId || '') === String(root.stateDatePromptRouteId || '') &&
  String(body.sendKey || '') === String(root.stateDatePromptSendKey || '') &&
  typeof body.idempotentReplay === 'boolean' &&
  typeof body.telegramSendAllowed === 'boolean' &&
  Number.isSafeInteger(Number(body.routeVersion));
const sendAllowed = valid &&
  body.idempotentReplay === false &&
  body.telegramSendAllowed === true &&
  body.status === 'prompt_sending';

return [{
  json: {
    ...root,
    stateDatePromptBeginValid: valid,
    stateDatePromptBeginReceipt: valid ? body : null,
    stateDatePromptSendingVersion: valid ? Number(body.routeVersion) : -1,
    stateDatePromptTelegramSendAllowed: sendAllowed,
    stateDatePromptBeginError: valid
      ? ''
      : String(body?.message || body?.error || body?.hint || 'state_date_prompt_begin_failed').slice(0, 1000)
  }
}];

'use strict';

const root = $('Code | Validate State Date Prompt Begin | StateDateRoute').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const messageId = String(body?.message_id ?? body?.result?.message_id ?? '').trim();
const chatId = String(body?.chat?.id ?? body?.result?.chat?.id ?? '').trim();
const sentAt = new Date().toISOString();
const exact = Boolean(
  root.stateDatePromptTelegramSendAllowed === true &&
  messageId &&
  chatId &&
  chatId === String(root.stateDatePromptChatId || '')
);
const receipt = exact ? {
  contractVersion: 'chelsea_state_date_prompt_telegram_receipt_v1',
  verified: true,
  routeId: String(root.stateDatePromptRouteId || ''),
  principalId: String(root.stateDatePromptPrincipalId || ''),
  chatId,
  messageId,
  sentAt
} : null;

return [{
  json: {
    ...root,
    stateDatePromptReceiptExact: exact,
    stateDatePromptTelegramReceipt: receipt,
    stateDatePromptTelegramError: exact
      ? ''
      : String(body?.description || body?.message || body?.error || 'state_date_prompt_receipt_invalid').slice(0, 1000),
    stateRpcBody: exact ? {
      p_route_id: String(root.stateDatePromptRouteId || ''),
      p_lease_token: String(root.stateDatePromptClaim?.lease_token || ''),
      p_expected_route_version: Number(root.stateDatePromptSendingVersion),
      p_send_key: String(root.stateDatePromptSendKey || ''),
      p_prompt_message_id: messageId,
      p_sent_at: sentAt,
      p_receipt_json: receipt
    } : {}
  }
}];

